RED on HEAD: no section. Mutation: an unscoped ``.flow-name-strip { margin-bottom: 0; }``. """ sheet = (REPO_ROOT / "s19_app/tui/styles.tcss").read_text(encoding="utf-8").replace("
", "
") marker = "/* batch-97 flow_execution" assert marker in sheet, "a scoped flow_execution section exists" section = sheet[sheet.index(marker):] # batch-97 Inc-8 (named supersession): the key bar's section is appended # after this one, so this section ends at the next batch-97 section. later = section.find("/* batch-97 ", len(marker)) section = section if later < 0 else section[:later] section = re.sub(r"/\*.*?\*/", "", section, flags=re.S) selectors = [s.strip() for block in re.findall(r"([^{}]+)\{", section) for s in block.split(",")] assert selectors, "the section holds rules" unscoped = [s for s in selectors if not s.startswith(("#fx_panel", "#screen_flow_execution"))] assert unscoped == [], unscoped try: old = subprocess.run( ["git", "show", "b514b07:s19_app/tui/styles.tcss"], cwd=REPO_ROOT, capture_output=True, check=True, ).stdout.decode("utf-8").replace("
